  function inspectionFields(phase,min=0){return `<fieldset class="full vehicle-inspection"><legend>${esc(tr(phase==='start'?'فحص بداية الشفت':'فحص نهاية الشفت',phase==='start'?'Start-of-shift inspection':'End-of-shift inspection'))}</legend><div class="form-columns">${field(tr('قراءة عداد المسافة الفعلية (كم)','Actual odometer (km)'),'inspection_odometer','',{type:'number',min,step:1,required:true})}<div class="fuel-control"><svg viewBox="0 0 200 118" aria-hidden="true"><path d="M20 100 A80 80 0 0 1 180 100" fill="none" stroke="#dde4df" stroke-width="15"/><path d="M20 100 A80 80 0 0 1 44 43" fill="none" stroke="#b83625" stroke-width="15"/><path d="M156 43 A80 80 0 0 1 180 100" fill="none" stroke="#176646" stroke-width="15"/><text x="12" y="116">E</text><text x="94" y="30">½</text><text x="179" y="116">F</text><line class="fuel-needle" x1="100" y1="100" x2="26" y2="100" stroke="#a94710" stroke-width="4"/><circle cx="100" cy="100" r="6" fill="#a94710"/></svg><label>${esc(tr('مستوى البنزين الفعلي %','Actual fuel level %'))}<input name="inspection_fuel" type="number" min="0" max="100" step="1" required placeholder="0–100"></label><input class="fuel-slider" type="range" min="0" max="100" step="1" value="50" aria-label="${esc(tr('تحديد مؤشر البنزين','Set fuel gauge'))}"></div>${Object.entries(inspectionItems).map(([key,label])=>`<label>${esc(tr(...label))}<select name="inspection_${key}" required><option value="">${esc(tr('اختر نتيجة الفحص','Select inspection result'))}</option><option value="ok">${esc(tr('سليم','OK'))}</option><option value="issue">${esc(tr('يحتاج متابعة','Needs attention'))}</option></select></label>`).join('')}${textarea(tr('ملاحظات الفحص — إلزامية عند وجود مشكلة','Inspection notes — required for issues'),'inspection_notes','')}</div></fieldset>`;}
