  function orderRows(rows){return rows.map(o=>`<tr data-order-id="${esc(o.id)}"><td><button class="quiet order-reference" data-action="order-detail" data-id="${esc(o.id)}">${esc(orderLabel(o))}</button>${o.identity_kind==='guest'||o.customer_identity?.identity_kind==='guest'||o.customer?.identity_kind==='guest'?`<span class="pill warn">${esc(tr('ضيف — الجوال غير موثق','Guest — phone unverified'))}</span>`:''}${o.customer?.risk_alert?`<span class="pill warn">${esc(tr('طلب مشابه — راجع','Similar request — review'))}</span>`:''}${o.customer?.requires_operational_confirmation&&!o.customer?.operational_confirmation?`<span class="pill warn">${esc(tr('بانتظار اتصال تشغيلي','Operational call required'))}</span>`:''}</td><td>${esc(o.customer?.neighborhood||o.neighborhood||o.address||'—')}</td><td>${esc(branchLabel(o))}</td><td>${duration(o.timings?.preparation)}</td><td>${duration(o.timings?.delivery)}</td><td class="money">${esc(money(o.total_halalas))}</td><td>${esc(o.driver_name||tr('غير مسند','Unassigned'))}</td><td>${badge(o.preparation_status||o.status)} ${performanceBadge(o.performance)}</td></tr>`).join('');}
