  function modal(title, html, onSubmit) { clearInterval(printerRefresh);printerRefresh=null; state.closureDirty=false;if($('#modal').open)$('#modal').close();$('#modal-title').textContent = title; $('#modal-body').innerHTML = html; $('#modal').showModal();hideUnavailableActions(); const form = $('#modal-body form'); if (form && onSubmit) form.addEventListener('submit', async e => { e.preventDefault(); const b = $('button[type=submit]', form); const error = $('.form-error', form); if (error) error.textContent = ''; if (b) b.disabled = true; try { await onSubmit(new FormData(form), form, b); } catch (x) { if (error) error.textContent = x.message; else setStatus(x.message, true); } finally { if (b?.isConnected) b.disabled = false; } }); }
