  const incentiveStateName=s=>({eligible:tr('مستحق','Eligible'),excluded:tr('مستبعد بسبب السائق','Excluded: driver responsibility'),pending_review:tr('بانتظار تحديد المسؤولية','Responsibility pending'),awaiting_approval:tr('بانتظار اعتماد الشفت','Awaiting shift approval'),incomplete:tr('غير مكتمل','Incomplete')})[s]||s;
