  $('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('cancel',event=>{if(state.closureDirty){event.preventDefault();closeModal();}});$('#modal').addEventListener('close',()=>{state.closureDirty=false;});
  $('#language').addEventListener('click',()=>{state.lang=state.lang==='ar'?'en':'ar';localStorage.setItem('kps_ops_lang',state.lang);applyLanguage();if(state.user)loadPage();});
  $('#logout').addEventListener('click',async()=>{try{await mutation('/api/auth/logout',{},$('#logout'));showLogin();state.orders=[];state.shifts=[];state.conversations=[];state.chatHistory.clear();state.requestKeys.clear();}catch(x){setStatus(x.message,true);}});
  function staffRequestMessage() { return tr('إذا كان الرقم مسجلًا ومخولًا فسيصلك كود إلى بريده المسجل. قبول الطلب لا يؤكد وصول البريد.','If this number is registered and authorized, a code will be sent to its registered email. Acceptance does not confirm delivery.'); }
  $('#staff-code-request-form').addEventListener('submit',async e=>{
    e.preventDefault();const fd=new FormData(e.currentTarget),b=$('#staff-code-request-submit');b.disabled=true;$('#staff-code-request-error').textContent='';
    try{
      if(Date.now()<state.staffResendAt)throw new Error(tr('انتظر دقيقة قبل إعادة إرسال الكود.','Wait one minute before requesting another code.'));
      const d=await api('/api/identity/staff/code/request',{method:'POST',body:{phone:String(fd.get('phone')).trim(),brand_id:new URLSearchParams(location.search).get('brand_id')||'kps'}});
      if(!d.accepted||!d.challenge_id)throw new Error(tr('تعذر بدء التحقق. أعد المحاولة.','Could not start verification. Retry.'));
      state.staffChallenge=d.challenge_id;state.staffResendAt=Date.now()+60000;$('#staff-code-request-state').textContent=staffRequestMessage();$('#staff-code-verify-form').hidden=false;$('#staff-code-verify-form input[name=code]').value='';$('#staff-code-expiry').textContent=tr('إذا لم يصل الكود، أعد الإرسال بعد دقيقة من الزر أعلاه.','If the code does not arrive, request again after one minute using the button above.');$('#staff-code-verify-form input[name=code]').focus();
    }catch(x){$('#staff-code-request-error').textContent=x.message;}finally{b.disabled=false;}
  });
  $('#staff-code-change-phone').addEventListener('click',()=>{state.staffChallenge=null;$('#staff-code-verify-form').hidden=true;$('#staff-code-verify-form').reset();$('#staff-code-request-state').textContent='';$('#staff-code-request-form input[name=phone]').focus();});
  $('#staff-code-verify-form').addEventListener('submit',async e=>{
    e.preventDefault();const f=e.currentTarget,fd=new FormData(f),b=$('#staff-code-verify-submit');b.disabled=true;$('#staff-code-verify-error').textContent='';
    try{
      if(!state.staffChallenge)throw new Error(tr('أرسل كودًا جديدًا أولًا.','Request a new code first.'));
      const display_name=String(fd.get('display_name')||'').trim();const d=await api('/api/identity/staff/code/verify',{method:'POST',body:{challenge_id:state.staffChallenge,code:String(fd.get('code')).trim(),...(display_name?{display_name}:{})}});
      if(!d.user||d.user.role==='customer'||!d.csrf_token)throw new Error(tr('هذا الحساب غير مخول لدخول التشغيل.','This account is not authorized for operations.'));
      state.user=d.user;state.csrf=d.csrf_token;state.staffChallenge=null;f.reset();$('#staff-code-request-form').reset();showApp();
    }catch(x){$('#staff-code-verify-error').textContent=x.message;}finally{b.disabled=false;}
  });
  $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),button=$('#login-submit');button.disabled=true;$('#login-error').textContent='';try{const d=await api('/api/auth/login',{method:'POST',body:{username:String(fd.get('username')).trim(),password:fd.get('password')}});state.user=d.user;state.csrf=d.csrf_token;if(!state.user||state.user.role==='customer'||!state.csrf)throw new Error(tr('هذا الحساب ليس مخولًا لدخول التشغيل.','This account is not authorized for operations.'));f.reset();showApp();}catch(x){$('#login-error').textContent=x.message;}finally{button.disabled=false;}});
  async function init(){applyLanguage();const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('identity_challenge')&&fragment.has('identity_token')){history.replaceState(null,'',location.pathname+location.search);try{const d=await api('/api/identity/email/verify',{method:'POST',body:{challenge_id:fragment.get('identity_challenge'),token:fragment.get('identity_token')}});if(d.user?.role==='customer')throw new Error(tr('هذه هوية عميل. افتح المتجر.','This is a customer identity. Open the store.'));state.user=d.user;state.csrf=d.csrf_token;showApp();return;}catch(e){showLogin();$('#staff-code-request-error').textContent=e.message;return;}}try{const d=await api('/api/session');if(d.user&&d.user.role!=='customer'&&d.csrf_token&&!d.reauthentication_required){state.user=d.user;state.csrf=d.csrf_token;showApp();}else showLogin();}catch(x){showLogin();setStatus(x.message,true);}}
  window.addEventListener('beforeunload',e=>{if(state.closureDirty){e.preventDefault();e.returnValue='';}});
  window.addEventListener('online',()=>setStatus(tr('عاد الاتصال. حدّث البيانات أو أعد محاولة العملية غير المؤكدة.','Connection restored. Refresh data or retry the unconfirmed operation.')));
  window.addEventListener('offline',()=>setStatus(tr('الاتصال منقطع. العمليات المالية لا تؤكد حتى الحفظ على الخادم.','Connection offline. Financial operations require server confirmation.'),true));
  setInterval(()=>{if(!document.hidden&&navigator.onLine&&state.user&&!$('#modal').open&&!state.busy.size)pollConversation();},5000);
  let polling=false;setInterval(async()=>{if(state.page==='chat'&&!document.hidden&&navigator.onLine&&state.user){await pollInbox();return;}if(polling||state.loading||!state.user||document.hidden||!navigator.onLine||$('#modal').open||state.busy.size||state.page==='admin'||state.page==='accounting'||state.page==='chat'||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''))return;const draft=$('#message-form textarea');if(draft?.value.trim()||$('#message-form input[type=file]')?.files?.length)return;polling=true;const old=new Set((state.orders||[]).map(o=>o.id));try{await loadPage(true);if(state.page==='orders'&&state.orders.some(o=>!old.has(o.id))){setStatus(tr('وصل طلب جديد. القائمة محدثة.','A new order arrived. The list is refreshed.'));document.title=tr('طلب جديد — KPS ORDER','New order — KPS ORDER');}}finally{polling=false;}},15000);
  init();
